using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CoffeeFinish{static BindingFlags F=BindingFlags.Static|BindingFlags.NonPublic;static CoffeeFinish(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CoffeeFinish.request"))return;File.Delete("CoffeeFinish.request");try{Run();}catch(Exception e){File.AppendAllText("FinalEnvironmentRoadReview/CoffeeShopUpgrade.txt",e.ToString());}}static void Run(){const string D="Assets/Scenes/Oasis/CoffeeShopUpgrade";var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var master=scene.GetRootGameObjects().Single(g=>g.name=="Coffee Shop Front Back Upgrade");var old=AssetDatabase.LoadAssetAtPath<Mesh>(D+"/Coffee warm trim and steps.asset");var vertices=old.vertices;var ribs=new List<Vector3[]>(); // Recover the original traced tube center lines from initial builder vertex layout (16 ribs x16 segments x5 sides x6 vertices).
for(int ray=0;ray<16;ray++){var line=new List<Vector3>();for(int k=0;k<=16;k++){int segment=Math.Min(k,15);int start=(ray*16+segment)*30;var average=Vector3.zero;for(int side=0;side<5;side++){int idx=start+side*6+(k==16?2:0);average+=vertices[idx];}line.Add(average/5f);}ribs.Add(line.ToArray());} // Instead use native roof sampling below to avoid mesh optimization reordering.
var source=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>()).First(f=>f.name=="Circus_Circus_0 (1)");var native=PrefabUtility.GetCorrespondingObjectFromOriginalSource(source);var data=typeof(FinalPNGCityDetails).GetMethod("Read",F).Invoke(null,new object[]{native.sharedMesh});var p=(Vector3[])data.GetType().GetField("p").GetValue(data);var ids=(int[])data.GetType().GetField("ids").GetValue(data);var center=new Vector3(222.486f,26.1f,253.823f);var w=p.Select(source.transform.TransformPoint).Select(v=>v-center).ToArray();ribs.Clear();Func<float,float,float> h=(x,z)=>{float best=-100;for(int j=0;j<ids.Length;j+=3){var a=w[ids[j]];var b=w[ids[j+1]];var c=w[ids[j+2]];float det=(b.z-c.z)*(a.x-c.x)+(c.x-b.x)*(a.z-c.z);if(Mathf.Abs(det)<.0001f)continue;float u=((b.z-c.z)*(x-c.x)+(c.x-b.x)*(z-c.z))/det,v=((c.z-a.z)*(x-c.x)+(a.x-c.x)*(z-c.z))/det;if(u>=0&&v>=0&&u+v<=1)best=Mathf.Max(best,u*a.y+v*b.y+(1-u-v)*c.y);}return best;};for(int ray=0;ray<16;ray++){float a=ray*Mathf.PI*2/16;var line=new List<Vector3>();for(int k=0;k<=16;k++){float r=3.2f+k/16f*21;float x=Mathf.Sin(a)*r,z=Mathf.Cos(a)*r;float y=h(x,z);if(y>8)line.Add(new Vector3(x,y+.07f,z));}if(line.Count>2)ribs.Add(line.ToArray());}var fresh=StackHouse3DSigns.BuildCoffeeTrim(ribs);old.Clear();old.indexFormat=fresh.indexFormat;old.vertices=fresh.vertices;old.uv=fresh.uv;var marks=new List<Vector4>();fresh.GetUVs(3,marks);old.SetUVs(3,marks);old.triangles=fresh.triangles;old.normals=fresh.normals;old.tangents=fresh.tangents;old.RecalculateBounds();EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(fresh);var wrap=AssetDatabase.LoadAssetAtPath<Mesh>(D+"/Coffee recessed existing atlas wrap.asset");var wp=wrap.vertices;for(int i=0;i<wp.Length;i++)if(wp[i].y<1)wp[i].y=1.86f;wrap.vertices=wp;var uv=wrap.uv;for(int i=0;i<uv.Length;i++){uv[i]=new Vector2(i%4==0||i%4==3?.615f:.664f,i%4<2?.781f:.823f);}wrap.uv=uv;wrap.RecalculateBounds();EditorUtility.SetDirty(wrap);foreach(Transform station in master.transform)foreach(Transform child in station)if(child.name.Contains("raised coffee sign")){float side=child.localPosition.z>0?1:-1;child.localPosition=new Vector3(0,6.53f,side*29.45f);PrefabUtility.RecordPrefabInstancePropertyModifications(child);}foreach(Transform station in master.transform){var image=station.Find("Recessed shopfront image wrap using original building atlas");if(image){image.gameObject.SetActive(false);PrefabUtility.RecordPrefabInstancePropertyModifications(image.gameObject);}}PrefabUtility.ApplyPrefabInstance(master,InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",F);var shops=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>()).Where(f=>f.name.StartsWith("Circus_Circus_0")).OrderByDescending(f=>f.transform.position.x).ToArray();foreach(int k in new[]{0,1}){var c=shops[k].GetComponent<Renderer>().bounds.center;capture.Invoke(null,new object[]{scene,c+new Vector3(0,-1,57),c+Vector3.down*4,"Coffee-Upgraded-"+(k+1)+"-Front-Day"});if(k==0)capture.Invoke(null,new object[]{scene,c+new Vector3(0,-1,-57),c+Vector3.down*4,"Coffee-Upgraded-1-Back-Day"});}var ctrl=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=ctrl.IsNight;try{ctrl.ApplyNight();var c=shops[0].GetComponent<Renderer>().bounds.center;capture.Invoke(null,new object[]{scene,c+new Vector3(0,-1,57),c+Vector3.down*4,"Coffee-Upgraded-1-Front-Night"});}finally{if(night)ctrl.ApplyNight();else ctrl.ApplyDay();}File.AppendAllText("FinalEnvironmentRoadReview/CoffeeShopUpgrade.txt","\nFINISH: both signs moved clear of original entrance panels; platform raised to local pavement; original storefront wrap crop aspect corrected. Scene and prefab saved.");}}

